'use strict';
(() => {
 const dialog=$('#activityDialog'),canvas=$('#activityCanvas');
 let scene=null,frameId=null,lastFrame=0,keys=new Set(),returnAfterDecorating=false;
 const menus={home:['sit','nap','sleep','cook','snack','shower','read','tidy','dance'],beach:['swim','fish','sunbathe','jog','stretch','walk','sit'],cafe:['meal','cafe-work','sit','read'],library:['study','read','sit'],market:['market-work','meal','sit']};
 function prop(id,type,x,y,w,h,action,extra={}){return {id,type,x,y,w,h,action,blocks:true,...extra};}
 function buildScene(place){const type=activitySceneType(place),size=roomSize();const view={place,type,cols:type==='beach'?12:type==='home'?size.cols+3:9,rows:type==='beach'?9:type==='home'?size.rows+3:7,props:[],actor:{x:2.5,y:5.5},route:[],current:null,pose:'idle',returnPoint:null,zoom:innerWidth<620?1.45:1,elapsed:0,moveClock:0,phase:0,heading:{x:1,y:0},hover:null,message:'Click the floor to walk. Click an object to use it.'};
  if(type==='home'){
   for(const item of state.furniture.filter(i=>i.x!==null)){const s=furnitureSize(item);view.props.push(prop(item.uid,item.type,item.x+1,item.y+1,s.w,s.h,({bed:'sleep',sofa:'sit',chair:'sit',desk:'read',shelf:'read',table:'snack'}[item.type])||null));}
   view.props.push(prop('window-bench','bench',2.1,view.rows-.8,2.2,.65,'sit'),prop('kitchen','kitchen',view.cols-1.15,.7,.9,1.6,'cook'),prop('shower','shower',view.cols-1.15,3.25,.9,1.5,'shower'));
   view.actor={x:view.cols-1.5,y:view.rows-1.5};
  }else if(type==='beach'){
   view.props=[prop('swimming','swim-zone',7,2,3,3,'swim',{blocks:false}),prop('pier','dock',4.6,6.2,3.2,.9,'fish',{blocks:false}),prop('sun-lounger','lounger',1.1,1.6,1,2,'sunbathe'),prop('beach-bench','bench',1.1,7.2,2.1,.65,'sit'),prop('palm-one','palm',.3,.4,.6,.6,null),prop('palm-two','palm',3.6,1,.6,.6,null)];view.actor={x:3.5,y:5.5};
  }else if(type==='cafe'){
   view.props=[prop('counter','counter',1,.6,5,1.2,'cafe-work'),prop('table-one','cafe-table',1.3,3.3,1.5,1.5,'meal'),prop('table-two','cafe-table',5.5,3.2,1.5,1.5,'meal'),prop('cafe-bench','bench',2.3,6,2.1,.65,'sit'),prop('cafe-plant','plant',7.4,.6,.8,.8,null)];view.actor={x:7.5,y:5.5};
  }else if(type==='library'){
   view.props=[prop('book-wall','shelf',.6,.5,5.8,.8,'read'),prop('study-desk','desk',2,3,2.7,1.2,'study'),prop('reading-chair','chair',6,4.5,1,1,'sit'),prop('library-plant','plant',7.3,.7,.8,.8,null)];view.actor={x:7.5,y:5.5};
  }else{
   view.props=[prop('market-stall','market-stall',.7,.5,5,1.5,'market-work'),prop('market-table','cafe-table',1.3,4,1.5,1.4,'meal'),prop('market-bench','bench',4.5,5.8,2.3,.6,'sit'),prop('produce-crate','crate',6.5,2.5,1,1,null)];view.actor={x:7.5,y:5.5};
  }return view;
 }
 function walkable(view,x,y){if(x<0||y<0||x>=view.cols||y>=view.rows)return false;const cx=x+.5,cy=y+.5;return !view.props.some(p=>p.blocks&&cx>=p.x&&cx<p.x+p.w&&cy>=p.y&&cy<p.y+p.h);}
 function pathTo(view,destination){const start={x:Math.floor(view.actor.x),y:Math.floor(view.actor.y)},goal={x:Math.floor(destination.x),y:Math.floor(destination.y)},key=p=>p.x+','+p.y;if(!walkable(view,goal.x,goal.y))return null;const queue=[start],seen=new Map([[key(start),null]]);for(let i=0;i<queue.length;i++){const p=queue[i];if(key(p)===key(goal))break;for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const n={x:p.x+dx,y:p.y+dy};if(!walkable(view,n.x,n.y)||seen.has(key(n)))continue;seen.set(key(n),p);queue.push(n);}}if(!seen.has(key(goal)))return null;const route=[];let p=goal;while(p&&key(p)!==key(start)){route.unshift({x:p.x+.5,y:p.y+.5});p=seen.get(key(p));}return route;}
 function targetFor(id){const v=scene;let p=v.props.find(p=>p.action===id);if(['nap','sleep'].includes(id))p=v.props.find(p=>p.type==='bed')||v.props.find(p=>p.type==='bench');if(['read','snack'].includes(id)&&v.type==='home')p=v.props.find(p=>p.type==='desk')||v.props.find(p=>p.type==='bench');if(['walk','jog','stretch'].includes(id))return {anchor:{x:3.5,y:4.5},posePoint:{x:3.5,y:4.5},prop:null};if(['tidy','dance'].includes(id))return {anchor:{x:v.cols-2.5,y:v.rows-2.5},posePoint:null,prop:null};p=p||v.props.find(p=>p.type==='bench')||v.props[0];const point={x:p.x+p.w*.5,y:p.y+p.h*.55};return {anchor:point,posePoint:['shelf','desk','table','cafe-table','counter','kitchen','market-stall'].includes(p.type)?null:point,prop:p};}
 function nearestApproach(target){let result=null,best=Infinity;for(let x=0;x<scene.cols;x++)for(let y=0;y<scene.rows;y++){if(!walkable(scene,x,y))continue;const dest={x:x+.5,y:y+.5},route=pathTo(scene,dest);if(!route)continue;const distance=Math.hypot(dest.x-target.anchor.x,dest.y-target.anchor.y)+route.length*.015;if(distance<best){best=distance;result={point:dest,route};}}return result;}
 function needs(){if(!scene)return;$('#sceneNeeds').innerHTML=`<span>ENERGY<b>${state.energy}%</b></span><span>FULLNESS<b>${state.hunger}%</b></span><span>MOOD<b>${state.mood}%</b></span>`;$('#sceneTally').textContent=`${Object.keys(state.activityStats).length} activities tried · ${Object.values(state.activityStats).reduce((n,v)=>n+v,0)} little moments enjoyed. Your story saves automatically.`;}
 function renderActions(){if(!scene)return;$('#sceneActions').innerHTML=menus[scene.type].map(id=>{const q=activityQuote(id),available=activityAvailable(id),hours=q.minutes>=60?Math.floor(q.minutes/60)+' hr'+(q.minutes%60?' '+q.minutes%60+' min':''):q.minutes+' min';const reward=q.pay?' · +'+cash(q.pay):q.cost?' · '+cash(q.cost):' · free';return `<button class="scene-activity ${scene.current?.id===id?'selected':''}" data-scene-action="${id}" ${available.ok?'':'disabled'} title="${available.ok?q.description:available.message}"><span>${q.icon}</span><span><b>${q.name}</b><small>${hours+reward}<br>${q.energy>=0?'+':''}${q.energy} energy · ${q.mood>=0?'+':''}${q.mood} mood</small></span><span>↗</span></button>`;}).join('');$('#sceneActions').querySelectorAll('[data-scene-action]').forEach(b=>b.onclick=()=>startAction(b.dataset.sceneAction));needs();}
 function status(title,message){$('#sceneActivityTitle').textContent=title;$('#sceneActivityStatus').textContent=message;}
 function stopAction(message=true){if(!scene)return;const swimming=scene.type==='beach'&&scene.actor.x>=5.5,old=scene.current;if(old)cancelActivity(old.session);if(scene.returnPoint&&!swimming)scene.actor={...scene.returnPoint};scene.returnPoint=null;scene.current=null;scene.route=[];scene.pose='idle';$('#sceneFinish').disabled=true;$('#sceneActivityProgress').style.width='0%';if(message){if(swimming){scene.route=pathTo(scene,{x:4.5,y:4.5})||[];status('Heading back to shore.','A few easy strokes, then back onto the sand.');}else status('A little room to move.','Click the floor, explore, or try another activity.');}renderActions();}
 function startAction(id,selectedProp){if(!scene)return false;const available=activityAvailable(id);if(!available.ok){status('Take a little care first.',available.message);return false;}stopAction(false);const target=targetFor(id);if(selectedProp){target.prop=selectedProp;target.anchor={x:selectedProp.x+selectedProp.w*.5,y:selectedProp.y+selectedProp.h*.55};target.posePoint=['shelf','desk','table','cafe-table','counter','kitchen','market-stall'].includes(selectedProp.type)?null:{...target.anchor};}const approach=nearestApproach(target);if(!approach){status('A little rearranging might help.','There isn’t a clear route. Try moving furniture, or choose another activity.');return false;}const result=beginActivity(id);if(!result.ok){status('Not just yet.',result.message);return false;}scene.current={id,session:result.session,quote:result.quote,target,approach:approach.point,elapsed:0,started:false,settled:false,loopIndex:0};scene.route=approach.route;$('#sceneFinish').disabled=false;status('On your way…','Your character is walking over. The activity starts when you arrive.');renderActions();if(!scene.route.length)enterPose();return true;}
 function enterPose(){if(!scene?.current)return;const a=scene.current;a.started=true;scene.returnPoint={...a.approach};scene.pose=a.quote.pose;const snap=['sit','sleep','read','eat','fish','sunbathe','swim','shower'].includes(scene.pose);scene.actor=snap&&a.target.posePoint?{...a.target.posePoint}:{...a.approach};if(scene.pose==='swim')scene.actor={x:7.5,y:3.5};status(a.quote.name,a.quote.description);$('#sceneCaption').textContent=scene.pose==='swim'?'You’re swimming. Click the water or use the controls to swim around.':'Watch your character enjoy the moment. Space stands up or stops.';}
 function completeCurrent(){if(!scene?.current||scene.current.settled)return false;const current=scene.current;scene.route=[];if(!current.started)enterPose();const result=finishActivity(current.session);current.settled=true;current.elapsed=6;$('#sceneFinish').disabled=true;$('#sceneActivityProgress').style.width='100%';if(result.ok)status(result.quote.name+' · complete',result.message+' Move when you’re ready, or try it again.');else{status('The moment ended.',result.message);scene.pose='idle';}renderActions();return result.ok;}
 function moveTo(destination){if(!scene)return false;stopAction(false);const target={x:Math.floor(destination.x)+.5,y:Math.floor(destination.y)+.5},route=pathTo(scene,target);if(!route){status('There’s something in the way.','Try a free patch of floor, or rearrange your furniture.');return false;}scene.route=route;status(scene.type==='beach'&&target.x>=5.5?'Heading into the water.':'A little exploring.','Click an object to use it, or choose an activity.');$('#sceneCaption').textContent='Click to move · E to use something nearby · Space to stop';return true;}
 function nudge(direction){if(!scene)return;const delta={left:[-1,0],right:[1,0],up:[0,-1],down:[0,1]}[direction];if(delta)moveTo({x:Math.floor(scene.actor.x)+delta[0]+.5,y:Math.floor(scene.actor.y)+delta[1]+.5});}
 function interact(){if(!scene)return;const p=scene.props.filter(p=>p.action).sort((a,b)=>Math.hypot(scene.actor.x-a.x-a.w/2,scene.actor.y-a.y-a.h/2)-Math.hypot(scene.actor.x-b.x-b.w/2,scene.actor.y-b.y-b.h/2))[0];if(p&&Math.hypot(scene.actor.x-p.x-p.w/2,scene.actor.y-p.y-p.h/2)<2.8)startAction(p.action,p);else status('Have a little look around.','Walk closer to an object and press E, or click it to walk over.');}
 function stepRoute(dt){if(!scene.route.length)return;let left=dt*3.3;while(scene.route.length&&left>0){const p=scene.route[0],dx=p.x-scene.actor.x,dy=p.y-scene.actor.y,d=Math.hypot(dx,dy);if(d>0)scene.heading={x:dx/d,y:dy/d};if(d<=left){scene.actor={...p};scene.route.shift();left-=d;}else{scene.actor.x+=dx/d*left;scene.actor.y+=dy/d*left;left=0;}}}
 function advanceScene(dt){if(!scene)return;scene.phase+=dt;scene.moveClock+=dt;if(keys.size&&scene.moveClock>.18){scene.moveClock=0;if(!scene.route.length)nudge([...keys].at(-1));}stepRoute(dt);const a=scene.current;if(a){if(!a.started&&!scene.route.length)enterPose();if(a.started){a.elapsed+=dt;if(!a.settled){$('#sceneActivityProgress').style.width=Math.min(100,a.elapsed/6*100)+'%';if(a.elapsed>=6)completeCurrent();}if(['swim','jog','walk','market-work','cafe-work'].includes(scene.pose)){let loop;if(scene.pose==='swim')loop=[{x:7.5,y:2.5},{x:10.5,y:4.5},{x:8.5,y:5.5},{x:7.5,y:3.5}];else if(scene.type==='beach')loop=[{x:3.5,y:4.5},{x:4.5,y:6.5},{x:1.5,y:5.5}];else loop=[a.approach,{x:a.approach.x+1,y:a.approach.y}];if(!scene.route.length){a.loopIndex=(a.loopIndex+1)%loop.length;const route=pathTo(scene,loop[a.loopIndex]);if(route)scene.route=route;}}}}}
 function draw(){if(scene)KoraSceneArt.draw(scene,canvas,matchMedia('(prefers-reduced-motion: reduce)').matches?0:scene.phase);}
 function frame(now){if(!scene||!dialog.open){frameId=null;return;}if(now-lastFrame>=32){const dt=Math.min(.12,Math.max(0,(now-lastFrame)/1000));lastFrame=now;if(!document.hidden&&!$('#phoneDialog').open){advanceScene(dt);draw();}}frameId=requestAnimationFrame(frame);}
 function closeScene(){if(scene?.current)cancelActivity(scene.current.session);scene=null;keys.clear();if(frameId!==null)cancelAnimationFrame(frameId);frameId=null;if(dialog.open)dialog.close();window.drawCity?.();}
 async function openScene(place=state.location,action){if(travelling){toast('Finish your journey first.');return false;}if(!activitySceneType(place))return false;if(place==='studio'&&state.home!=='studio'){toast('Rent the Olive Court studio before entering.');return false;}if(scene?.place===place&&dialog.open){if(action)startAction(action);return true;}closeScene();if(state.location!==place){selected=place;if(!await travel(place))return false;}scene=buildScene(place);$('#sceneTitle').textContent=scene.type==='home'?'Welcome home.':scene.type==='beach'?'A little closer to the sea.':PLACES.find(p=>p.id===place).name;$('#scenePlace').textContent=PLACES.find(p=>p.id===place).name;$('#sceneKicker').textContent=scene.type==='home'?'YOUR OWN LITTLE CORNER OF THE CITY':'A LITTLE LIFE, UP CLOSE';$('#sceneDecorate').hidden=scene.type!=='home';$('#sceneCaption').textContent=scene.type==='beach'?'Click the water to swim, the pier to fish, or the sand to explore.':'Click the floor to walk. Click furniture or an object to use it.';status('Make a little moment.','Explore at your own pace. Try an activity to see your character do it.');$('#sceneActivityProgress').style.width='0%';$('#sceneFinish').disabled=true;renderActions();dialog.showModal();canvas.focus();draw();lastFrame=performance.now();frameId=requestAnimationFrame(frame);if(action)startAction(action);return true;}
 window.playSceneAction=action=>{if(!ACTIVITIES[action]||!ACTIVITIES[action].types.includes(activitySceneType(state.location)))return false;openScene(state.location,action);return true;};
 Object.assign(window,{openActivityScene:openScene,closeActivityScene:closeScene});
 window.KoraScenes={open:openScene,close:closeScene,start:startAction,finish:completeCurrent,stop:stopAction,move:moveTo,inspect:()=>scene?{place:scene.place,pose:scene.pose,x:scene.actor.x,y:scene.actor.y,walking:scene.route.length>0,activity:scene.current?.id||null,settled:!!scene.current?.settled,props:scene.props.map(p=>({id:p.id,type:p.type,x:p.x,y:p.y,w:p.w,h:p.h}))}:null};
 $('#sceneExit').onclick=closeScene;$('#sceneStop').onclick=()=>{stopAction();draw();};$('#sceneFinish').onclick=()=>{completeCurrent();draw();};$('#sceneInteract').onclick=interact;$('#scenePhone').onclick=()=>$('#phoneBtn').onclick();$('#sceneZoomIn').onclick=()=>{if(scene){scene.zoom=Math.min(2.5,scene.zoom+.2);draw();}};$('#sceneZoomOut').onclick=()=>{if(scene){scene.zoom=Math.max(.75,scene.zoom-.2);draw();}};
 $('#sceneDecorate').onclick=async()=>{closeScene();await openApartment();returnAfterDecorating=true;};$('#dialog').addEventListener('close',()=>{if(returnAfterDecorating&&!$('#dialog').open){returnAfterDecorating=false;openScene(state.home==='studio'?'studio':'home');}});
 dialog.addEventListener('close',()=>{if(!dialog.open)closeScene();});dialog.addEventListener('cancel',()=>{if(scene?.current)cancelActivity(scene.current.session);});
 canvas.addEventListener('click',event=>{if(!scene)return;const target=KoraSceneArt.pick(scene,canvas,event.clientX,event.clientY);if(target.prop?.action)startAction(target.prop.action,target.prop);else if(target.point)moveTo(target.point);draw();});
 canvas.addEventListener('mousemove',event=>{if(scene){scene.hover=KoraSceneArt.pick(scene,canvas,event.clientX,event.clientY).prop?.id||null;}});
 const directions={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down'};
 dialog.addEventListener('keydown',event=>{if(!scene||$('#phoneDialog').open)return;if(directions[event.key]){event.preventDefault();keys.add(directions[event.key]);if(!event.repeat)nudge(directions[event.key]);}else if(event.key.toLowerCase()==='e'){event.preventDefault();interact();}else if(event.code==='Space'||event.key===' '){event.preventDefault();stopAction();}});dialog.addEventListener('keyup',event=>{if(directions[event.key])keys.delete(directions[event.key]);});
 window.addEventListener('blur',()=>keys.clear());document.querySelectorAll('[data-scene-move]').forEach(button=>{const direction=button.dataset.sceneMove;button.onclick=()=>nudge(direction);button.onpointerdown=event=>{event.preventDefault();keys.add(direction);nudge(direction);};button.onpointerup=button.onpointercancel=button.onpointerleave=()=>keys.delete(direction);});
 new ResizeObserver(draw).observe(canvas);$('#apartmentBtn').onclick=()=>openScene(state.home==='studio'?'studio':'home');
})();
